import { Component, ComponentInterface, Element, h, Prop } from '@stencil/core';
import {
  fromEvent,
  merge,
  Observable,
  of,
  OperatorFunction,
  race,
  Subject,
  switchMap,
  take,
  takeUntil,
  tap,
  timer,
} from 'rxjs';

/**
 * @slot default - default slot for anchor items
 * @slot label - named slot 'label' for the anchor label
 */
@Component({
  tag: 'groupui-anchor',
  styleUrl: 'anchor.scss',
  shadow: true,
})
export class Anchor implements ComponentInterface {
  @Element() host: HTMLElement;

  /**
   * Reference ID of the scroll container
   */
  @Prop({ reflect: true }) readonly scrollContainerIdRef: string;

  private intersectionsObserver: IntersectionObserver;

  private destroy: Subject<void>;
  private intersection: Subject<string>;
  private click: Subject<void>;
  private scroll: Subject<void>;
  private scrollEnd: Subject<void>;

  private scrollPositions = new Map<string, number>();

  componentDidLoad() {
    this.focusFirstAnchorElement();
    this.createIntersectionObservers();
    this.listenToAnchorItemClicks();
    this.listenToManualScroll();
    this.listenToScrollEvents();
  }

  private listenToScrollEvents() {
    if (!this.scrollContainer()) return;
    fromEvent(this.scrollContainer(), 'scroll')
      .pipe(takeUntil(this.destroy))
      .subscribe(() => this.scroll.next());

    fromEvent(this.scrollContainer(), 'scrollend')
      .pipe(takeUntil(this.destroy))
      .subscribe(() => this.scrollEnd.next());
  }

  private listenToManualScroll() {
    this.intersection.pipe(takeUntil(this.destroy)).subscribe((id) => {
      this.focusAnchorElement(this.anchorItemForId(id));
    });
  }

  connectedCallback(): void {
    this.destroy = new Subject<void>();
    this.intersection = new Subject<string>();
    this.click = new Subject<void>();
    this.scroll = new Subject<void>();
    this.scrollEnd = new Subject<void>();
  }

  disconnectedCallback() {
    this.intersectionsObserver?.disconnect();
    this.destroy.next();
    this.destroy.complete();
    this.intersection.complete();
    this.click.complete();
    this.scroll.complete();
    this.scrollEnd.complete();
  }

  private isLabelSlotProvided(): boolean {
    return !!this.host.querySelector('[slot="label"]');
  }

  private referencedAnchorElements(): HTMLElement[] {
    const idRefs = Array.from(this.host.querySelectorAll('groupui-anchor-item')).map(
      (anchor: HTMLGroupuiAnchorItemElement) => {
        return `#${anchor.idRef}`;
      }
    );
    const idRefElements = document.querySelectorAll(idRefs.join(', '));
    return Array.from(idRefElements) as HTMLElement[];
  }

  private referencedAnchorElement(id: string): HTMLElement | null {
    return this.referencedAnchorElements().find((element) => {
      return element.id === id;
    });
  }

  private focusFirstAnchorElement() {
    if (this.anchorItems().length === 0) return;
    this.focusAnchorElement(this.anchorItems()[0]);
  }

  private focusAnchorElement(item: HTMLElement) {
    this.anchorItems().forEach((element) => {
      element.removeAttribute('selected');
    });
    item.setAttribute('selected', '');
  }

  private previousReferencedAnchorElement(id: string): HTMLElement | null {
    const currentIndex = this.referencedAnchorElements().findIndex((element) => element.id === id);
    if (currentIndex > 0) {
      return this.referencedAnchorElements()[currentIndex - 1];
    }
    return null;
  }

  private listenToAnchorItemClicks() {
    this.anchorItems().forEach((anchorItem) => {
      fromEvent(anchorItem, 'click')
        .pipe(
          tap((e) => this.handleClickSideEffects(e, anchorItem)),
          this.waitUntilScrollingSettled(),
          takeUntil(this.destroy)
        )
        .subscribe(() => {
          this.focusAnchorElement(anchorItem);
        });
    });
  }

  private handleClickSideEffects(e: Event, anchorItem: HTMLGroupuiAnchorItemElement): void {
    e.preventDefault();
    this.click.next();
    const referencedElement = this.referencedAnchorElement(anchorItem.idRef);
    if (referencedElement) {
      referencedElement.scrollIntoView({ behavior: 'smooth' });
    }
  }

  /**
   * Custom Operator: Waits for scrolling to fully settle.
   * If no scroll event fires within 100ms, proceeds immediately (no scrolling needed).
   * Otherwise, waits for 'scrollend' and then ensures that no intersection events
   * fire for 200ms before continuing.
   */
  private waitUntilScrollingSettled<T>(): OperatorFunction<T, unknown> {
    return switchMap(() =>
      race(timer(100), this.scroll.pipe(take(1))).pipe(
        take(1),
        switchMap((e) => (this.timerWon(e) ? this.noScrollNeeded() : this.waitForScrollEndAndIntersections())),
        takeUntil(this.click)
      )
    );
  }

  private timerWon(raceResult: unknown): boolean {
    return raceResult === 0;
  }

  private noScrollNeeded(): Observable<unknown> {
    return of(null);
  }

  /**
   * Waits for 'scrollend' and then waits for 200ms
   * without any further intersection events firing.
   */
  private waitForScrollEndAndIntersections(): Observable<unknown> {
    return this.scrollEnd.pipe(
      takeUntil(this.click),
      take(1),
      switchMap(() => this.waitForIntersectionsToSettle())
    );
  }

  /**
   * Waits until no intersection events have fired for 200ms.
   */
  private waitForIntersectionsToSettle(): Observable<unknown> {
    return merge(of(null), this.intersection).pipe(
      switchMap(() => timer(200)),
      take(1),
      takeUntil(this.click)
    );
  }

  private scrollContainer(): HTMLElement | null {
    return document.querySelector(`#${this.scrollContainerIdRef}`);
  }

  private createIntersectionObservers() {
    this.intersectionsObserver = new IntersectionObserver(
      (entries) => {
        let elementToFocus: HTMLElement | null;
        for (const entry of entries) {
          const id = entry.target.id;

          if (!this.scrollPositions.has(id)) {
            this.scrollPositions.set(id, entry.boundingClientRect.top);
            continue;
          }

          const oldScrollTop = this.scrollPositions.get(id);
          const newScrollTop = entry.boundingClientRect.top;

          if (this.referencedElementIsLeavingTopEdge(oldScrollTop, newScrollTop, entry.isIntersecting)) {
            elementToFocus = this.previousReferencedAnchorElement(id);
          }

          if (this.referencedElementIsEnteringTopEdge(oldScrollTop, newScrollTop, entry.isIntersecting)) {
            elementToFocus = this.referencedAnchorElement(id);
          }

          this.scrollPositions.set(id, newScrollTop);
        }

        if (elementToFocus) {
          this.intersection.next(elementToFocus.id);
        }
      },
      {
        threshold: 1,
        root: this.scrollContainer(),
        rootMargin: '-1px 0px 0px 0px',
      }
    );

    this.referencedAnchorElements().forEach((element) => {
      this.intersectionsObserver.observe(element);
    });
  }

  private referencedElementIsEnteringTopEdge(oldScroll: number, newScroll: number, isIntersecting: boolean): boolean {
    return oldScroll > newScroll && !isIntersecting;
  }

  private referencedElementIsLeavingTopEdge(oldScroll: number, newScroll: number, isIntersecting: boolean): boolean {
    return oldScroll < newScroll && isIntersecting;
  }

  private anchorItemForId(id: string): HTMLGroupuiAnchorItemElement | null {
    return document.querySelector(`[id-ref="${id}"]`) as HTMLGroupuiAnchorItemElement;
  }

  private anchorItems(): HTMLGroupuiAnchorItemElement[] {
    return Array.from(this.host.querySelectorAll('groupui-anchor-item'));
  }

  render() {
    return (
      <div class="container">
        {this.isLabelSlotProvided() && <slot name="label"></slot>}
        <div class="items">
          <slot></slot>
        </div>
      </div>
    );
  }
}
